<?php if (!isset($findingResult)) { http_response_code(404); exit; } ?>
<?php if (!$findingResult['ok']): ?><div class="empty-state" role="status">No fue posible cargar los hallazgos.</div><?php elseif ($findingResult['data']===[]): ?><div class="empty-state">No hay hallazgos en esta página.</div><?php else: ?>
<div class="table-scroll" role="region" aria-label="Hallazgos" tabindex="0"><table class="data-table"><thead><tr><th scope="col">Hallazgo</th><th scope="col">Estado</th><th scope="col">Severidad</th><th scope="col">Responsable</th><th scope="col">Evidencias</th><th scope="col">Acciones</th></tr></thead><tbody>
<?php foreach ($findingResult['data'] as $row): ?><tr><td data-label="Hallazgo"><strong>#<?= e($row['numero']??'') ?></strong> <?= e($row['titulo']??'') ?></td><td data-label="Estado"><span class="badge badge-neutral"><?= e(finding_states()[$row['estado']??'']??'') ?></span></td><td data-label="Severidad"><?= e(finding_severities()[$row['severidad']??'']??'') ?></td><td data-label="Responsable"><?= e($row['responsable']['nombre']??'Sin asignar') ?></td><td data-label="Evidencias"><?= e($row['evidencias_count']??0) ?></td><td data-label="Acciones"><a class="table-link" href="<?= e(page_url('hallazgo',['id'=>positive_id($row['id']??null)])) ?>">Ver hallazgo</a></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
